const crypto = require('crypto');

function stableStringify(v) {
  if (v === null || v === undefined) return 'null';
  const t = typeof v;
  if (t === 'number' || t === 'boolean') return JSON.stringify(v);
  if (t === 'string') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
  if (t === 'object') {
    const keys = Object.keys(v).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + stableStringify(v[k])).join(',') + '}';
  }
  return JSON.stringify(String(v));
}

const row = $input.first().json;
const body = row.body && typeof row.body === 'object' ? row.body : row;
const out = body.output && typeof body.output === 'object' ? body.output : body;

const sectorEnv = String($env.SECTOR_ID || 'SECTOR-DESCONOCIDO').trim();
const coreId = String($env.CORE_ID || 'nucleo-opex').trim();
const sectorTag = sectorEnv.replace(/\s+/g, '-');

let ef = out.eficiencia_general_pct;
if (ef == null && typeof out.oee_score === 'number') {
  ef = out.oee_score <= 1 ? out.oee_score * 100 : out.oee_score;
}
const conf = ef != null ? Math.max(0, Math.min(100, Math.round(Number(ef)))) : 55;

const recs = Array.isArray(out.recomendaciones_opex) ? out.recomendaciones_opex.slice(0, 12) : [];
const decisionText =
  'OpEx ' +
  coreId +
  ' @ ' +
  sectorEnv +
  ' | eficiencia_pct=' +
  (ef != null ? String(ef) : 'n/a') +
  ' | oee=' +
  (out.oee_score != null ? String(out.oee_score) : 'n/a');

const snapshot = {
  consumo_energia_kwh: out.consumo_energia_kwh,
  consumo_agua_litros: out.consumo_agua_litros,
  coste_operativo_eur: out.coste_operativo_eur,
  mtbf_horas: out.mtbf_horas,
  mttr_horas: out.mttr_horas,
  roi_estimado_mejoras: out.roi_estimado_mejoras
};
let ctx = JSON.stringify(snapshot);
if (ctx.length > 1900) ctx = ctx.slice(0, 1900) + '…';

const auditBody = {
  kind: 'ia',
  agente_id: coreId,
  actor: coreId,
  decision: decisionText,
  confianza: conf,
  tags: ['#ia-decision', '#opex', '#sector-' + sectorTag],
  contexto: 'OPEX_ANALYSIS ' + ctx,
  status: ef != null && Number(ef) < 60 ? 'WARNING' : 'OK',
  event: 'OPEX_ANALYSIS',
  details: {
    sector_id: sectorEnv,
    core_id: coreId,
    recomendaciones_opex: recs,
    fuente: 'excelencia_operativa'
  }
};

const secret = String($env.CASTUO_AUDIT_WEBHOOK_SECRET || '').trim();
let signature = '';
if (secret) {
  signature = crypto.createHmac('sha256', secret).update(stableStringify(auditBody), 'utf8').digest('hex');
}

return [
  {
    json: {
      auditBody,
      hmacSignature: signature,
      hmacRequired: !!secret,
      auditUrl: String($env.CASTUO_TRILLIZO_AUDIT_URL || 'http://n8n-trillizo:5678/webhook/audit-trigger')
    }
  }
];
